// Pagination.tsx
import React from "react";

type PaginationProps = {
  currentPage: number;          // 1-based
  totalItems: number;
  pageSize: number;
  onPageChange: (page: number) => void;
  siblingCount?: number;        // pages shown on each side of the current page
};

const ELLIPSIS = "…" as const;
type PageItem = number | typeof ELLIPSIS;

const range = (start: number, end: number): number[] =>
  Array.from({ length: Math.max(end - start + 1, 0) }, (_, i) => start + i);

export function getPageItems(
  currentPage: number,
  totalPages: number,
  siblingCount = 1
): PageItem[] {
  // Exactly one page (or zero results): show just page 1, i.e. "1 through 1".
  if (totalPages <= 1) return [1];

  const maxVisible = siblingCount * 2 + 5; // first, last, current, 2 ellipses
  if (totalPages <= maxVisible) return range(1, totalPages);

  const left = Math.max(currentPage - siblingCount, 2);
  const right = Math.min(currentPage + siblingCount, totalPages - 1);
  const showLeftEllipsis = left > 2;
  const showRightEllipsis = right < totalPages - 1;

  const items: PageItem[] = [1];
  if (showLeftEllipsis) items.push(ELLIPSIS);
  items.push(...range(left, right));
  if (showRightEllipsis) items.push(ELLIPSIS);
  items.push(totalPages);
  return items;
}

export function Pagination({
  currentPage,
  totalItems,
  pageSize,
  onPageChange,
  siblingCount = 1,
}: PaginationProps) {
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const page = Math.min(Math.max(currentPage, 1), totalPages);
  const items = getPageItems(page, totalPages, siblingCount);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button
            disabled={page <= 1}
            onClick={() => onPageChange(page - 1)}
            aria-label="Previous page"
          >
            ‹
          </button>
        </li>

        {items.map((item, i) =>
          item === ELLIPSIS ? (
            <li key={`e${i}`} aria-hidden="true">{ELLIPSIS}</li>
          ) : (
            <li key={item}>
              <button
                onClick={() => onPageChange(item)}
                aria-current={item === page ? "page" : undefined}
                disabled={item === page}
              >
                {item}
              </button>
            </li>
          )
        )}

        <li>
          <button
            disabled={page >= totalPages}
            onClick={() => onPageChange(page + 1)}
            aria-label="Next page"
          >
            ›
          </button>
        </li>
      </ul>
    </nav>
  );
}
