// Pagination.tsx
import React from "react";

type Props = {
  totalItems: number;
  pageSize: number;
  currentPage: number;           // 1-based
  onPageChange: (page: number) => void;
  siblingCount?: number;         // pages shown on each side of current
};

export function getPageCount(totalItems: number, pageSize: number): number {
  if (pageSize <= 0) return 1;
  // Always at least 1 page, so empty results still render "1"
  return Math.max(1, Math.ceil(totalItems / pageSize));
}

export type PageItem = number | "ellipsis-start" | "ellipsis-end";

export function getPageItems(
  pageCount: number,
  currentPage: number,
  siblingCount = 1
): PageItem[] {
  // Exactly one page: pages 1 through 1
  if (pageCount <= 1) return [1];

  const current = Math.min(Math.max(1, currentPage), pageCount);
  const range = (a: number, b: number) =>
    Array.from({ length: b - a + 1 }, (_, i) => a + i);

  // Small enough to show everything
  const maxWithoutEllipsis = siblingCount * 2 + 5;
  if (pageCount <= maxWithoutEllipsis) return range(1, pageCount);

  const left = Math.max(current - siblingCount, 2);
  const right = Math.min(current + siblingCount, pageCount - 1);
  const showStartEllipsis = left > 2;
  const showEndEllipsis = right < pageCount - 1;

  const items: PageItem[] = [1];
  if (showStartEllipsis) items.push("ellipsis-start");
  else items.push(...range(2, left - 1));
  items.push(...range(left, right));
  if (showEndEllipsis) items.push("ellipsis-end");
  else items.push(...range(right + 1, pageCount - 1));
  items.push(pageCount);
  return items;
}

export function Pagination({
  totalItems,
  pageSize,
  currentPage,
  onPageChange,
  siblingCount = 1,
}: Props) {
  const pageCount = getPageCount(totalItems, pageSize);
  const current = Math.min(Math.max(1, currentPage), pageCount);
  const items = getPageItems(pageCount, current, siblingCount);

  return (
    <nav aria-label="Pagination">
      <button
        disabled={current <= 1}
        onClick={() => onPageChange(current - 1)}
        aria-label="Previous page"
      >
        ‹
      </button>

      {items.map((item) =>
        typeof item === "number" ? (
          <button
            key={item}
            aria-current={item === current ? "page" : undefined}
            disabled={item === current}
            onClick={() => onPageChange(item)}
          >
            {item}
          </button>
        ) : (
          <span key={item} aria-hidden="true">…</span>
        )
      )}

      <button
        disabled={current >= pageCount}
        onClick={() => onPageChange(current + 1)}
        aria-label="Next page"
      >
        ›
      </button>
    </nav>
  );
}
