// Pagination.tsx
import React from "react";

type Props = {
  totalPages: number;
  currentPage: number;               // 1-based
  onPageChange: (page: number) => void;
  siblings?: number;                 // pages shown on each side of current
};

type Item = number | "ellipsis-left" | "ellipsis-right";

export function getPageItems(total: number, current: number, siblings = 1): Item[] {
  // Always at least one page, so exactly one page of results yields [1].
  const last = Math.max(1, Math.floor(total));
  const page = Math.min(Math.max(1, current), last);

  const start = Math.max(2, page - siblings);
  const end = Math.min(last - 1, page + siblings);

  const items: Item[] = [1];
  if (start > 2) items.push("ellipsis-left");
  for (let p = start; p <= end; p++) items.push(p);
  if (end < last - 1) items.push("ellipsis-right");
  if (last > 1) items.push(last);
  return items;
}

export function Pagination({ totalPages, currentPage, onPageChange, siblings = 1 }: Props) {
  const last = Math.max(1, Math.floor(totalPages));
  const page = Math.min(Math.max(1, currentPage), last);
  const items = getPageItems(last, page, siblings);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button disabled={page === 1} onClick={() => onPageChange(page - 1)}>
