          typeof item === "number" ? (
            <li key={item}>
              <button
                aria-current={item === page ? "page" : undefined}
                disabled={item === page}
                onClick={() => onPageChange(item)}
              >
                {item}
              </button>
            </li>
          ) : (
            <li key={item} aria-hidden="true">…</li>
          )
        )}

        <li>
          <button disabled={page === last} onClick={() => onPageChange(page + 1)}>
            Next
          </button>
        </li>
      </ul>
    </nav>
  );
}
