// Pagination.tsx
import React from "react";

export interface PaginationProps {
  totalItems: number;
  pageSize: number;
  currentPage: number; // 1-based
  onPageChange: (page: number) => void;
  /** Max numbered buttons to show before collapsing with ellipses. */
  maxVisible?: number;
}

/** Returns page numbers and "ellipsis" markers to render. */
export function getPageRange(
  current: number,
  total: number,
  maxVisible = 7
): Array<number | "ellipsis"> {
  // Covers total === 1: yields [1], i.e. "pages 1 through 1".
  if (total <= maxVisible) {
    return Array.from({ length: total }, (_, i) => i + 1);
  }

  const siblings = Math.max(1, Math.floor((maxVisible - 3) / 2));
  const start = Math.max(2, Math.min(current - siblings, total - maxVisible + 3));
  const end = Math.min(total - 1, Math.max(current + siblings, maxVisible - 2));

  const pages: Array<number | "ellipsis"> = [1];
  if (start > 2) pages.push("ellipsis");
  for (let p = start; p <= end; p++) pages.push(p);
  if (end < total - 1) pages.push("ellipsis");
  pages.push(total);
  return pages;
}

export function Pagination({
  totalItems,
  pageSize,
  currentPage,
  onPageChange,
  maxVisible = 7,
}: PaginationProps) {
  // Always at least one page, even with zero items.
  const totalPages = Math.max(1, Math.ceil(totalItems / Math.max(1, pageSize)));
  const page = Math.min(Math.max(1, currentPage), totalPages);
  const pages = getPageRange(page, totalPages, maxVisible);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button
            onClick={() => onPageChange(page - 1)}
            disabled={page <= 1}
            aria-label="Previous page"
          >
            ‹
          </button>
        </li>

        {pages.map((p, i) =>
          p === "ellipsis" ? (
            <li key={`e${i}`} aria-hidden="true">…</li>
          ) : (
            <li key={p}>
              <button
                onClick={() => onPageChange(p)}
                aria-current={p === page ? "page" : undefined}
                aria-label={`Page ${p}`}
                disabled={p === page}
              >
                {p}
              </button>
            </li>
          )
        )}

        <li>
          <button
            onClick={() => onPageChange(page + 1)}
            disabled={page >= totalPages}
            aria-label="Next page"
          >
            ›
          </button>
        </li>
      </ul>
    </nav>
  );
}
