// Pagination.tsx
import React from "react";

export interface PaginationProps {
  /** Total number of items across all pages. */
  totalItems: number;
  pageSize: number;
  /** 1-based current page. */
  currentPage: number;
  onPageChange: (page: number) => void;
  /** Number of page links shown around the current page. */
  siblingCount?: number;
}

/** Returns page numbers and "ellipsis" markers to render. */
export function getPageRange(
  totalPages: number,
  currentPage: number,
  siblingCount = 1
): Array<number | "ellipsis"> {
  // Zero results still counts as one (empty) page, so we always show "1".
  const total = Math.max(1, totalPages);

  // Exactly one page: shows pages 1 through 1.
  if (total === 1) return [1];

  const current = Math.min(Math.max(1, currentPage), total);
  const start = Math.max(2, current - siblingCount);
  const end = Math.min(total - 1, current + siblingCount);

  const range: Array<number | "ellipsis"> = [1];
  if (start > 2) range.push("ellipsis");
  for (let p = start; p <= end; p++) range.push(p);
  if (end < total - 1) range.push("ellipsis");
  range.push(total);
  return range;
}

export function Pagination({
  totalItems,
  pageSize,
  currentPage,
  onPageChange,
  siblingCount = 1,
}: PaginationProps) {
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const current = Math.min(Math.max(1, currentPage), totalPages);
  const pages = getPageRange(totalPages, current, siblingCount);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button
            onClick={() => onPageChange(current - 1)}
            disabled={current <= 1}
            aria-label="Previous page"
          >
            ‹
          </button>
        </li>

        {pages.map((p, i) =>
          p === "ellipsis" ? (
            <li key={`e${i}`} aria-hidden="true">…</li>
          ) : (
            <li key={p}>
              <button
                onClick={() => onPageChange(p)}
                aria-current={p === current ? "page" : undefined}
                disabled={p === current}
              >
                {p}
              </button>
            </li>
          )
        )}

        <li>
          <button
            onClick={() => onPageChange(current + 1)}
            disabled={current >= totalPages}
            aria-label="Next page"
          >
            ›
          </button>
        </li>
      </ul>
    </nav>
  );
}
```

