```tsx
// Pagination.tsx
import React from "react";

type PaginationProps = {
  totalItems: number;
  pageSize: number;
  currentPage: number;
  onPageChange: (page: number) => void;
  siblingCount?: number; // pages shown on each side of the current page
};

const ELLIPSIS = "…" as const;
type PageItem = number | typeof ELLIPSIS;

export function getPageRange(
  currentPage: number,
  totalPages: number,
  siblingCount = 1
): PageItem[] {
  // Always at least one page, so 0 items or exactly one page yields [1].
  const total = Math.max(1, totalPages);
  const current = Math.min(Math.max(1, currentPage), total);

  // Small enough to show everything: first + last + current + siblings + 2 ellipses
  const maxVisible = siblingCount * 2 + 5;
  if (total <= maxVisible) {
    return Array.from({ length: total }, (_, i) => i + 1); // total === 1 -> [1]
  }

  const left = Math.max(current - siblingCount, 2);
  const right = Math.min(current + siblingCount, total - 1);
  const items: PageItem[] = [1];

  if (left > 2) items.push(ELLIPSIS);
  for (let p = left; p <= right; p++) items.push(p);
  if (right < total - 1) items.push(ELLIPSIS);

  items.push(total);
  return items;
}

export function Pagination({
  totalItems,
  pageSize,
  currentPage,
  onPageChange,
  siblingCount = 1,
}: PaginationProps) {
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const current = Math.min(Math.max(1, currentPage), totalPages);
  const pages = getPageRange(current, totalPages, siblingCount);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button
            onClick={() => onPageChange(current - 1)}
            disabled={current <= 1}
            aria-label="Previous page"
          >
            ‹
          </button>
        </li>

        {pages.map((p, i) =>
          p === ELLIPSIS ? (
            <li key={`ellipsis-${i}`} aria-hidden="true">
              {ELLIPSIS}
            </li>
          ) : (
            <li key={p}>
              <button
                onClick={() => onPageChange(p)}
                aria-current={p === current ? "page" : undefined}
                aria-label={`Page ${p}`}
                disabled={p === current}
              >
                {p}
              </button>
            </li>
          )
        )}

        <li>
          <button
            onClick={() => onPageChange(current + 1)}
            disabled={current >= totalPages}
            aria-label="Next page"
          >
            ›
          </button>
        </li>
      </ul>
    </nav>
  );
}
```

**Single-page behavior** (`totalItems <= pageSize`):
- `totalPages` is clamped to at least 1, so the component never renders an empty list, even with 0 items.
- `getPageRange(1, 1)` returns `[1]`, so the only page button is "1", marked `aria-current="page"`.
- Previous and Next are both disabled because `current <= 1` and `current >= totalPages`.
- `currentPage` is clamped, so a stale value like `3` still resolves to page 1.

