// Pagination.tsx
import React from "react";

export interface PaginationProps {
  /** Total number of items across all pages */
  totalItems: number;
  pageSize: number;
  /** 1-based current page */
  currentPage: number;
  onPageChange: (page: number) => void;
  /** Pages shown on each side of the current page */
  siblingCount?: number;
}

type PageItem = number | "ellipsis-start" | "ellipsis-end";

const range = (start: number, end: number): number[] =>
  Array.from({ length: Math.max(end - start + 1, 0) }, (_, i) => start + i);

export function getPageItems(
  totalPages: number,
  currentPage: number,
  siblingCount = 1
): PageItem[] {
  // Exactly one page (or none): show just page 1
  if (totalPages <= 1) return [1];

  // Small enough to show every page without truncation
  const maxVisible = siblingCount * 2 + 5; // first, last, current, 2 ellipses, siblings
  if (totalPages <= maxVisible) return range(1, totalPages);

  const left = Math.max(currentPage - siblingCount, 2);
  const right = Math.min(currentPage + siblingCount, totalPages - 1);
  const showStartEllipsis = left > 2;
  const showEndEllipsis = right < totalPages - 1;

  const items: PageItem[] = [1];
  if (showStartEllipsis) items.push("ellipsis-start");
  items.push(...range(left, right));
  if (showEndEllipsis) items.push("ellipsis-end");
  items.push(totalPages);
  return items;
}

export function Pagination({
  totalItems,
  pageSize,
  currentPage,
  onPageChange,
  siblingCount = 1,
}: PaginationProps) {
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const page = Math.min(Math.max(currentPage, 1), totalPages);
  const items = getPageItems(totalPages, page, siblingCount);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button
            onClick={() => onPageChange(page - 1)}
            disabled={page <= 1}
            aria-label="Previous page"
          >
            Previous
          </button>
        </li>

        {items.map((item) =>
          typeof item === "number" ? (
            <li key={item}>
              <button
                onClick={() => onPageChange(item)}
                aria-current={item === page ? "page" : undefined}
                aria-label={`Page ${item}`}
                disabled={item === page}
              >
                {item}
              </button>
            </li>
          ) : (
            <li key={item} aria-hidden="true">
              …
            </li>
          )
        )}

        <li>
          <button
            onClick={() => onPageChange(page + 1)}
            disabled={page >= totalPages}
            aria-label="Next page"
          >
            Next
          </button>
        </li>
      </ul>
    </nav>
  );
}
```

