// Pagination.tsx
import React from "react";

export interface PaginationProps {
  totalItems: number;
  pageSize: number;
  currentPage: number;
  onPageChange: (page: number) => void;
  /** Max page buttons to show before collapsing with ellipses. */
  maxButtons?: number;
}

/** Returns page numbers (and "…" gaps) to render. */
export function getPageItems(
  totalPages: number,
  currentPage: number,
  maxButtons = 7
): Array<number | "ellipsis"> {
  // Exactly one page (or zero results): show just page 1.
  if (totalPages <= 1) return [1];

  if (totalPages <= maxButtons) {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }

  const items: Array<number | "ellipsis"> = [1];
  const siblings = Math.max(1, Math.floor((maxButtons - 5) / 2));
  const start = Math.max(2, currentPage - siblings);
  const end = Math.min(totalPages - 1, currentPage + siblings);

  if (start > 2) items.push("ellipsis");
  for (let p = start; p <= end; p++) items.push(p);
  if (end < totalPages - 1) items.push("ellipsis");

  items.push(totalPages);
  return items;
}

export function Pagination({
  totalItems,
  pageSize,
  currentPage,
  onPageChange,
  maxButtons = 7,
}: PaginationProps) {
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const page = Math.min(Math.max(1, currentPage), totalPages); // clamp
  const items = getPageItems(totalPages, page, maxButtons);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button disabled={page <= 1} onClick={() => onPageChange(page - 1)}>
            Previous
          </button>
        </li>

        {items.map((item, i) =>
          item === "ellipsis" ? (
            <li key={`e${i}`} aria-hidden="true">…</li>
          ) : (
            <li key={item}>
              <button
                aria-current={item === page ? "page" : undefined}
                disabled={item === page}
                onClick={() => onPageChange(item)}
              >
                {item}
              </button>
            </li>
          )
