// Pagination.tsx
import React from "react";

export interface PaginationProps {
  /** Total number of pages. Values below 1 are treated as 1. */
  totalPages: number;
  /** Current 1-based page. Clamped into [1, totalPages]. */
  currentPage: number;
  onPageChange: (page: number) => void;
  /** Pages shown on each side of the current page. */
  siblingCount?: number;
}

type Item = number | "ellipsis-left" | "ellipsis-right";

export function getPageItems(
  totalPages: number,
  currentPage: number,
  siblingCount = 1
): Item[] {
  const total = Math.max(1, Math.floor(totalPages));
  const current = Math.min(Math.max(1, currentPage), total);

  // Exactly one page: shows "1" through "1", i.e. just [1].
  if (total === 1) return [1];

  const start = Math.max(2, current - siblingCount);
  const end = Math.min(total - 1, current + siblingCount);

  const items: Item[] = [1];
  if (start > 2) items.push("ellipsis-left");
  for (let p = start; p <= end; p++) items.push(p);
  if (end < total - 1) items.push("ellipsis-right");
  items.push(total);
  return items;
}

export function Pagination({
  totalPages,
  currentPage,
  onPageChange,
  siblingCount = 1,
}: PaginationProps) {
  const total = Math.max(1, Math.floor(totalPages));
  const current = Math.min(Math.max(1, currentPage), total);
  const items = getPageItems(total, current, siblingCount);

  return (
    <nav aria-label="Pagination">
      <button
        type="button"
        disabled={current <= 1}
        onClick={() => onPageChange(current - 1)}
      >
        Previous
      </button>

      <ul style={{ display: "inline-flex", listStyle: "none", padding: 0 }}>
        {items.map((item) =>
          typeof item === "number" ? (
            <li key={item}>
              <button
                type="button"
                aria-current={item === current ? "page" : undefined}
                disabled={item === current}
                onClick={() => onPageChange(item)}
              >
                {item}
              </button>
            </li>
          ) : (
            <li key={item} aria-hidden="true">…</li>
          )
        )}
      </ul>

      <button
        type="button"
        disabled={current >= total}
        onClick={() => onPageChange(current + 1)}
      >
        Next
      </button>
    </nav>
  );
}
```

