 * siblings = how many pages to show on each side of the current page.
 */
export function getPageItems(
  currentPage: number,
  totalPages: number,
  siblings = 1
): PageItem[] {
  // Normalize bad input: always at least one page.
  const total = Math.max(1, Math.floor(totalPages));
  const current = Math.min(Math.max(1, Math.floor(currentPage)), total);

  // Small totals: show everything (covers the single-page case: [1]).
  const maxWithoutEllipsis = siblings * 2 + 5;
  if (total <= maxWithoutEllipsis) {
    return Array.from({ length: total }, (_, i) => i + 1);
