// Pagination.tsx
import React from "react";

export interface PaginationProps {
  totalItems: number;
  pageSize: number;
  currentPage: number; // 1-based
  onPageChange: (page: number) => void;
}

/** Returns the page numbers to display: [1] when there is exactly one page. */
export function getPageNumbers(totalItems: number, pageSize: number): number[] {
  if (pageSize <= 0) return [];
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  return Array.from({ length: totalPages }, (_, i) => i + 1);
}

export function Pagination({
  totalItems,
  pageSize,
  currentPage,
  onPageChange,
}: PaginationProps) {
  const pages = getPageNumbers(totalItems, pageSize);
  if (pages.length === 0) return null;

  const lastPage = pages[pages.length - 1];
  const current = Math.min(Math.max(currentPage, 1), lastPage);

  return (
    <nav aria-label="Pagination">
      <button
        disabled={current === 1}
        onClick={() => onPageChange(current - 1)}
      >
        Previous
      </button>

      {pages.map((page) => (
        <button
          key={page}
          aria-current={page === current ? "page" : undefined}
          disabled={page === current}
          onClick={() => onPageChange(page)}
        >
          {page}
        </button>
      ))}

      <button
        disabled={current === lastPage}
        onClick={() => onPageChange(current + 1)}
      >
        Next
      </button>
    </nav>
  );
}
```

With exactly one page of results (for example `totalItems=8, pageSize=10`), it renders a single button, "1", marked as the current page. Previous and Next are both disabled.

