```tsx
// Pagination.tsx
import React from "react";

export type PageItem = number | "ellipsis";

/** Returns the list of page items to display. For totalPages === 1 this is [1]. */
export function getPageRange(
  currentPage: number,
  totalPages: number,
  siblings = 1
): PageItem[] {
  const total = Math.max(1, Math.floor(totalPages));
  const current = Math.min(Math.max(1, Math.floor(currentPage)), total);

  // Small enough to show everything (covers total === 1 -> [1])
  const maxWithoutEllipsis = siblings * 2 + 5;
  if (total <= maxWithoutEllipsis) {
    return Array.from({ length: total }, (_, i) => i + 1);
  }

  const left = Math.max(current - siblings, 2);
  const right = Math.min(current + siblings, total - 1);
  const items: PageItem[] = [1];

  if (left > 2) items.push("ellipsis");
  for (let p = left; p <= right; p++) items.push(p);
  if (right < total - 1) items.push("ellipsis");

  items.push(total);
  return items;
}

interface PaginationProps {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  siblings?: number;
}

export function Pagination({
  currentPage,
  totalPages,
  onPageChange,
  siblings = 1,
}: PaginationProps) {
  const total = Math.max(1, Math.floor(totalPages));
  const current = Math.min(Math.max(1, currentPage), total);
  const items = getPageRange(current, total, siblings);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button
            onClick={() => onPageChange(current - 1)}
            disabled={current <= 1}
            aria-label="Previous page"
          >
            ‹
          </button>
        </li>

        {items.map((item, i) =>
          item === "ellipsis" ? (
            <li key={`e${i}`} aria-hidden="true">…</li>
          ) : (
            <li key={item}>
              <button
                onClick={() => onPageChange(item)}
                aria-current={item === current ? "page" : undefined}
                aria-label={`Page ${item}`}
                disabled={item === current}
              >
                {item}
              </button>
            </li>
          )
        )}

        <li>
          <button
            onClick={() => onPageChange(current + 1)}
            disabled={current >= total}
            aria-label="Next page"
          >
            ›
          </button>
        </li>
      </ul>
    </nav>
  );
}
