  if (showLeftEllipsis) items.push("ellipsis-start");
  else items.push(...range(2, left - 1));
  items.push(...range(left, right));
  if (showRightEllipsis) items.push("ellipsis-end");
  else items.push(...range(right + 1, total - 1));
  items.push(total);
  return items;
}

export function Pagination({
  totalItems,
  pageSize,
  currentPage,
  onPageChange,
  siblingCount = 1,
}: PaginationProps) {
  const totalPages = getTotalPages(totalItems, pageSize);
  const page = Math.min(Math.max(1, currentPage), totalPages);
  const items = getPageItems(page, totalPages, siblingCount);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button
            onClick={() => onPageChange(page - 1)}
            disabled={page <= 1}
            aria-label="Previous page"
          >
            ‹
          </button>
        </li>

        {items.map((item) =>
          typeof item === "number" ? (
            <li key={item}>
              <button
                onClick={() => onPageChange(item)}
                aria-current={item === page ? "page" : undefined}
                disabled={item === page}
              >
                {item}
              </button>
            </li>
          ) : (
            <li key={item} aria-hidden="true">…</li>
          )
        )}

        <li>
          <button
            onClick={() => onPageChange(page + 1)}
            disabled={page >= totalPages}
            aria-label="Next page"
          >
            ›
          </button>
        </li>
      </ul>
    </nav>
  );
}
