export function getPageRange(
  totalPages: number,
  currentPage: number,
  siblingCount = 1
): Array<number | "ellipsis"> {
  // Always at least one page, so zero results and exactly one page of results both yield [1].
  const total = Math.max(1, Math.floor(totalPages));
  const current = Math.min(Math.max(1, currentPage), total);

  // Exactly one page: pages 1 through 1.
