  // Exactly one page: 1 through 1.
  if (totalPages === 1) return [1];

  const page = Math.min(Math.max(current, 1), totalPages);
  const maxWithoutEllipsis = siblings * 2 + 5; // first, last, current, siblings, 2 ellipses

  if (totalPages <= maxWithoutEllipsis) {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }

  const left = Math.max(page - siblings, 2);
  const right = Math.min(page + siblings, totalPages - 1);
  const items: PageItem[] = [1];

  if (left > 2) items.push("ellipsis");
  for (let p = left; p <= right; p++) items.push(p);
  if (right < totalPages - 1) items.push("ellipsis");

  items.push(totalPages);
  return items;
}

interface PaginationProps {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  siblings?: number;
}

export function Pagination({
  currentPage,
  totalPages,
  onPageChange,
  siblings = 1,
}: PaginationProps) {
  const items = getPageItems(currentPage, totalPages, siblings);
  if (items.length === 0) return null;

  const page = Math.min(Math.max(currentPage, 1), totalPages);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button
            onClick={() => onPageChange(page - 1)}
            disabled={page <= 1}
            aria-label="Previous page"
          >
            ‹
          </button>
        </li>

        {items.map((item, i) =>
          item === "ellipsis" ? (
            <li key={`e${i}`} aria-hidden="true">…</li>
          ) : (
            <li key={item}>
              <button
                onClick={() => onPageChange(item)}
                aria-current={item === page ? "page" : undefined}
                disabled={item === page}
              >
                {item}
              </button>
            </li>
          )
        )}

        <li>
          <button
            onClick={() => onPageChange(page + 1)}
            disabled={page >= totalPages}
            aria-label="Next page"
          >
            ›
          </button>
        </li>
      </ul>
    </nav>
  );
}
```

With `totalPages = 1`, the component renders a single page button, "1", marked as the current page. Previous and Next are both disabled.

