// Pagination.tsx
import React from "react";

export interface PaginationProps {
  /** Total number of items across all pages */
  totalItems: number;
  /** Items per page */
  pageSize: number;
  /** Current 1-based page */
  currentPage: number;
  onPageChange: (page: number) => void;
  /** Max page buttons shown before collapsing with ellipses */
  maxButtons?: number;
}

type PageItem = number | "ellipsis-start" | "ellipsis-end";

export function getPageItems(
  totalPages: number,
  currentPage: number,
  maxButtons = 7
): PageItem[] {
  // Always at least one page, so zero or one result still shows "1".
  const total = Math.max(1, totalPages);

  if (total <= maxButtons) {
    return Array.from({ length: total }, (_, i) => i + 1);
  }

  const siblings = Math.max(1, Math.floor((maxButtons - 5) / 2));
  const start = Math.max(2, currentPage - siblings);
  const end = Math.min(total - 1, currentPage + siblings);

  const items: PageItem[] = [1];
  if (start > 2) items.push("ellipsis-start");
  for (let p = start; p <= end; p++) items.push(p);
  if (end < total - 1) items.push("ellipsis-end");
  items.push(total);
  return items;
}

export function Pagination({
  totalItems,
  pageSize,
  currentPage,
  onPageChange,
  maxButtons = 7,
}: PaginationProps) {
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const page = Math.min(Math.max(1, currentPage), totalPages);
  const items = getPageItems(totalPages, page, maxButtons);

  return (
    <nav aria-label="Pagination">
      <button
        onClick={() => onPageChange(page - 1)}
        disabled={page <= 1}
        aria-label="Previous page"
      >
        ‹
      </button>

      {items.map((item) =>
        typeof item === "number" ? (
          <button
            key={item}
            onClick={() => onPageChange(item)}
            aria-current={item === page ? "page" : undefined}
            disabled={item === page}
          >
            {item}
          </button>
        ) : (
          <span key={item} aria-hidden="true">…</span>
        )
      )}

      <button
        onClick={() => onPageChange(page + 1)}
        disabled={page >= totalPages}
        aria-label="Next page"
      >
        ›
      </button>
    </nav>
  );
}
