// Pagination.tsx
import React from "react";

export interface PaginationProps {
  totalItems: number;
  pageSize: number;
  currentPage: number;               // 1-based
  onPageChange: (page: number) => void;
  siblingCount?: number;             // pages shown on each side of current
}

/** Returns page numbers and "..." gaps. For one page it returns [1]. */
export function getPageItems(
  totalPages: number,
  currentPage: number,
  siblingCount = 1
): Array<number | "..."> {
  if (totalPages <= 1) return [1]; // exactly one page (or no results): just "1"

  const start = Math.max(2, currentPage - siblingCount);
  const end = Math.min(totalPages - 1, currentPage + siblingCount);

  const items: Array<number | "..."> = [1];
  if (start > 2) items.push("...");
  for (let p = start; p <= end; p++) items.push(p);
  if (end < totalPages - 1) items.push("...");
  items.push(totalPages);
  return items;
}

export function Pagination({
  totalItems,
  pageSize,
  currentPage,
  onPageChange,
  siblingCount = 1,
}: PaginationProps) {
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const page = Math.min(Math.max(1, currentPage), totalPages);
  const items = getPageItems(totalPages, page, siblingCount);

  return (
    <nav aria-label="Pagination">
      <button
        disabled={page <= 1}
        onClick={() => onPageChange(page - 1)}
      >
        Previous
      </button>

      <ul style={{ display: "inline-flex", listStyle: "none", padding: 0 }}>
        {items.map((item, i) =>
          item === "..." ? (
            <li key={`gap-${i}`} aria-hidden="true">…</li>
          ) : (
            <li key={item}>
              <button
                aria-current={item === page ? "page" : undefined}
                disabled={item === page}
                onClick={() => onPageChange(item)}
              >
                {item}
              </button>
            </li>
          )
        )}
      </ul>

      <button
        disabled={page >= totalPages}
        onClick={() => onPageChange(page + 1)}
      >
        Next
      </button>
    </nav>
  );
}
